{
  "name": "Computer Repair Process",
  "resources": [
    {
      "name": "CRS",
      "capacity": 1,
      "resource_type": "human"
    },
    {
      "name": "Customer",
      "capacity": 1,
      "resource_type": "external_party"
    }
  ],
  "events": [
    {
      "id": "event_start_cust",
      "name": "Defective computer brought in",
      "event_position": "start",
      "trigger_type": "none",
      "message_name": null
    },
    {
      "id": "event_end_cust_take_home",
      "name": "Take computer home unrepaired",
      "event_position": "end",
      "trigger_type": "none",
      "message_name": null
    },
    {
      "id": "event_end_cust_repaired",
      "name": "Take repaired computer home",
      "event_position": "end",
      "trigger_type": "none",
      "message_name": null
    },
    {
      "id": "event_start_crs",
      "name": "Defective computer received",
      "event_position": "start",
      "trigger_type": "message",
      "message_name": "Defective Computer"
    },
    {
      "id": "event_end_crs_cancelled",
      "name": "Process terminated (declined)",
      "event_position": "end",
      "trigger_type": "none",
      "message_name": null
    },
    {
      "id": "event_end_crs_finished",
      "name": "Computer handed over",
      "event_position": "end",
      "trigger_type": "message",
      "message_name": "Repaired Computer"
    }
  ],
  "tasks": [
    {
      "id": "task_check_defect",
      "name": "Check defect and prepare cost calculation",
      "bpmn_type": "bpmn:ManualTask",
      "resource_name": "CRS",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": [],
      "output_data_ids": [
        "data_cost_calculation"
      ]
    },
    {
      "id": "task_decide_cost",
      "name": "Decide if costs are acceptable",
      "bpmn_type": "bpmn:UserTask",
      "resource_name": "Customer",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": [
        "data_cost_calculation"
      ],
      "output_data_ids": []
    },
    {
      "id": "task_repair_hw",
      "name": "Check and repair hardware",
      "bpmn_type": "bpmn:ManualTask",
      "resource_name": "CRS",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": [],
      "output_data_ids": []
    },
    {
      "id": "task_repair_sw",
      "name": "Check and configure software",
      "bpmn_type": "bpmn:ManualTask",
      "resource_name": "CRS",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": [],
      "output_data_ids": []
    },
    {
      "id": "task_test_hw",
      "name": "Test system functionality (HW)",
      "bpmn_type": "bpmn:ManualTask",
      "resource_name": "CRS",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": [],
      "output_data_ids": []
    },
    {
      "id": "task_test_sw",
      "name": "Test system functionality (SW)",
      "bpmn_type": "bpmn:ManualTask",
      "resource_name": "CRS",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": [],
      "output_data_ids": []
    }
  ],
  "gateways": [
    {
      "id": "gw_cost_acceptable",
      "name": "Costs acceptable?",
      "gateway_type": "exclusive",
      "branch_probabilities": null,
      "branch_conditions": [
        {
          "flow_id": "flow_cust_accept",
          "condition": "Costs acceptable"
        },
        {
          "flow_id": "flow_cust_decline",
          "condition": "Costs not acceptable"
        }
      ]
    },
    {
      "id": "gw_crs_decision",
      "name": "Customer decision received",
      "gateway_type": "exclusive",
      "branch_probabilities": null,
      "branch_conditions": [
        {
          "flow_id": "flow_crs_continue",
          "condition": "Accepted"
        },
        {
          "flow_id": "flow_crs_decline",
          "condition": "Declined"
        }
      ]
    },
    {
      "id": "gw_repair_split",
      "name": "Parallel repair tasks",
      "gateway_type": "parallel",
      "branch_probabilities": null,
      "branch_conditions": null
    },
    {
      "id": "gw_repair_join",
      "name": "Parallel repair completed",
      "gateway_type": "parallel",
      "branch_probabilities": null,
      "branch_conditions": null
    },
    {
      "id": "gw_check_errors",
      "name": "Error detected?",
      "gateway_type": "exclusive",
      "branch_probabilities": null,
      "branch_conditions": [
        {
          "flow_id": "flow_error_yes",
          "condition": "Error detected"
        },
        {
          "flow_id": "flow_error_no",
          "condition": "No error"
        }
      ]
    }
  ],
  "sequence_flows": [
    {
      "id": "flow_cust_1",
      "source_id": "event_start_cust",
      "target_id": "task_decide_cost",
      "condition_name": null
    },
    {
      "id": "flow_cust_2",
      "source_id": "task_decide_cost",
      "target_id": "gw_cost_acceptable",
      "condition_name": null
    },
    {
      "id": "flow_cust_decline",
      "source_id": "gw_cost_acceptable",
      "target_id": "event_end_cust_take_home",
      "condition_name": "Costs not acceptable"
    },
    {
      "id": "flow_cust_accept",
      "source_id": "gw_cost_acceptable",
      "target_id": "event_end_cust_repaired",
      "condition_name": "Costs acceptable"
    },
    {
      "id": "flow_crs_1",
      "source_id": "event_start_crs",
      "target_id": "task_check_defect",
      "condition_name": null
    },
    {
      "id": "flow_crs_2",
      "source_id": "task_check_defect",
      "target_id": "gw_crs_decision",
      "condition_name": null
    },
    {
      "id": "flow_crs_decline",
      "source_id": "gw_crs_decision",
      "target_id": "event_end_crs_cancelled",
      "condition_name": "Declined"
    },
    {
      "id": "flow_crs_continue",
      "source_id": "gw_crs_decision",
      "target_id": "gw_repair_split",
      "condition_name": "Accepted"
    },
    {
      "id": "flow_split_hw",
      "source_id": "gw_repair_split",
      "target_id": "task_repair_hw",
      "condition_name": null
    },
    {
      "id": "flow_split_sw",
      "source_id": "gw_repair_split",
      "target_id": "task_repair_sw",
      "condition_name": null
    },
    {
      "id": "flow_hw_test",
      "source_id": "task_repair_hw",
      "target_id": "task_test_hw",
      "condition_name": null
    },
    {
      "id": "flow_sw_test",
      "source_id": "task_repair_sw",
      "target_id": "task_test_sw",
      "condition_name": null
    },
    {
      "id": "flow_join_hw",
      "source_id": "task_test_hw",
      "target_id": "gw_repair_join",
      "condition_name": null
    },
    {
      "id": "flow_join_sw",
      "source_id": "task_test_sw",
      "target_id": "gw_repair_join",
      "condition_name": null
    },
    {
      "id": "flow_crs_check",
      "source_id": "gw_repair_join",
      "target_id": "gw_check_errors",
      "condition_name": null
    },
    {
      "id": "flow_error_yes",
      "source_id": "gw_check_errors",
      "target_id": "gw_repair_split",
      "condition_name": "Error detected"
    },
    {
      "id": "flow_error_no",
      "source_id": "gw_check_errors",
      "target_id": "event_end_crs_finished",
      "condition_name": "No error"
    }
  ],
  "pools": [
    {
      "id": "pool_customer",
      "name": "Customer",
      "element_ids": [
        "event_start_cust",
        "task_decide_cost",
        "gw_cost_acceptable",
        "event_end_cust_take_home",
        "event_end_cust_repaired"
      ]
    },
    {
      "id": "pool_crs",
      "name": "CRS",
      "element_ids": [
        "event_start_crs",
        "task_check_defect",
        "gw_crs_decision",
        "event_end_crs_cancelled",
        "gw_repair_split",
        "task_repair_hw",
        "task_test_hw",
        "task_repair_sw",
        "task_test_sw",
        "gw_repair_join",
        "gw_check_errors",
        "event_end_crs_finished"
      ]
    }
  ],
  "message_flows": [
    {
      "id": "msg_flow_computer",
      "source_id": "event_start_cust",
      "target_id": "event_start_crs",
      "name": "Defective Computer"
    },
    {
      "id": "msg_flow_cost_calc",
      "source_id": "task_check_defect",
      "target_id": "task_decide_cost",
      "name": "Repair Cost Calculation"
    },
    {
      "id": "msg_flow_decision",
      "source_id": "task_decide_cost",
      "target_id": "gw_crs_decision",
      "name": "Decision (Accept/Reject)"
    },
    {
      "id": "msg_flow_repaired_computer",
      "source_id": "event_end_crs_finished",
      "target_id": "event_end_cust_repaired",
      "name": "Repaired Computer"
    }
  ],
  "data_objects": [
    {
      "id": "data_cost_calculation",
      "name": "Repair Cost Calculation"
    }
  ],
  "data_stores": [],
  "inter_arrival_time": {
    "distribution": "fixed",
    "value": 1.0,
    "unit": "minutes",
    "is_placeholder": true,
    "source": "default_missing_duration"
  },
  "simulation_duration": null,
  "simulation_duration_unit": "hours"
}
